  static success(message) { if (!this.quiet && this.verbose) this.line('OK',message,ANSI.green); }
  static step(message) { if (!this.quiet) this.line('SETUP',message); }
  static warn(message) { this.line('WARN',message,ANSI.yellow); }
  static error(message) { this.line('ERROR',message,ANSI.red); }
