function resolveDataDir(hint = '/data') {
  const tryDir = (dir) => {
    try {
      fs.mkdirSync(dir, { recursive: true });
      fs.accessSync(dir, fs.constants.W_OK);
      const probe = path.join(dir, '.amyrax-write-test');
      fs.writeFileSync(probe, 'ok'); fs.unlinkSync(probe);
      return true;
    } catch { return false; }
  };
  const explicit = process.env.AMYRAX_DATA_DIR || process.env.FILE_PATH;
  if (explicit) {
    const dir = UpgradeSupport.dataPath(explicit);
    if (!tryDir(dir)) throw new Error('AMYRAX_DATA_DIR is not writable: '+dir);
    resolveDataDir.info = {dir,source:'AMYRAX_DATA_DIR'};
    return dir;
  }
  if (hint && hint !== '/data') {
    const dir = UpgradeSupport.dataPath(hint);
    if (!tryDir(dir)) throw new Error('Configured data directory is not writable: '+dir);
    resolveDataDir.info = {dir,source:'configured data'};
    return dir;
  }
  const candidates = [
    [process.env.RAILWAY_VOLUME_MOUNT_PATH, 'Railway volume (RAILWAY_VOLUME_MOUNT_PATH)'],
    [hint, 'default ' + hint],
    [path.join(process.cwd(), 'amyrax-data'), './amyrax-data fallback'],
    [path.join(__dirname, 'amyrax-data'), 'app-dir amyrax-data fallback'],
    [path.join(os.tmpdir(), 'amyrax-data'), 'temp-dir fallback']
  ];
  const oldDirs = UpgradeSupport.previousDataDirectories(process.cwd(),__dirname,os.tmpdir());
  for (const oldDir of oldDirs) {
    if (fs.existsSync(oldDir) && fs.existsSync(path.join(path.dirname(oldDir),'amyrax-data'))) {
      throw new Error('Two data stores exist. Set AMYRAX_DATA_DIR explicitly before starting.');
    }
  }
  const existing = [...candidates.map(([dir])=>dir), ...oldDirs].filter(Boolean).find(dir =>
    ['auth.json','state.json','users.json','traffic.json'].some(name=>fs.existsSync(path.join(dir,name))));
  if (existing) {
    const dir = UpgradeSupport.dataPath(existing);
    if (!tryDir(dir)) throw new Error('Existing Amyrax data directory is not writable: '+dir);
    resolveDataDir.info = {dir,source:'saved data'};
    return dir;
  }
  for (const [dir, source] of candidates) {
    if (dir && tryDir(dir)) { resolveDataDir.info = { dir, source }; return dir; }
  }
  const dir = path.join(os.tmpdir(), 'amyrax-data');
  resolveDataDir.info = { dir, source: 'temp-dir fallback (not writable?)' };
  return dir;
}

